const courses = ['欢迎与介绍','什么是教练？','什么是焦点解决','如何构建一个教练会谈？','未来完美场景教练问题','成功的过去和进步的标志','How do I coach?','How do I coach 2?','What is the ICF Code of Ethics?','ICF Code of Ethics Core Competency 3','Mandated Clients','Subsequent Sessions','Core Competencies 1–4','Core Competencies 5–6','Core Competency 7','Core Competency 8','Coaching Practice','Coaching Practice','Coaching Decisions and Coaching Practice','Coaching Habits and Coaching Practice','Coaching Practice','Coaching Practice','Coaching Practice','Next Steps'];
const initial = [['08/15','andy','工作不满意，是否要换工作',.5],['08/19','hetty','工作新任务，压力大想调整',.5],['08/29','hetty','工作卡点，老板不认可',.5],['09/04','andy','想要有更多选择的可能性',.5],['09/05','fanzi','工作卡点，找到状态',.5],['09/09','mayo','工作很忙但状态不佳，想调整状态',.5]];

async function setup(DB) {
  await DB.batch([
    DB.prepare('CREATE TABLE IF NOT EXISTS acc_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)'),
    DB.prepare('CREATE TABLE IF NOT EXISTS coaching_sessions (id INTEGER PRIMARY KEY, session_date TEXT NOT NULL, client TEXT NOT NULL, topic TEXT NOT NULL, duration REAL NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)'),
    DB.prepare('CREATE INDEX IF NOT EXISTS idx_coaching_sessions_date ON coaching_sessions(session_date)'),
    DB.prepare("INSERT OR IGNORE INTO acc_settings (key,value) VALUES ('completed_courses','[0,1,2,3,4,5]')")
  ]);
  const count = await DB.prepare('SELECT COUNT(*) AS count FROM coaching_sessions').first();
  if (!count.count) await DB.batch(initial.map(r => DB.prepare('INSERT INTO coaching_sessions (session_date,client,topic,duration) VALUES (?,?,?,?)').bind(...r)));
}
async function state(DB) {
  const saved = await DB.prepare("SELECT value FROM acc_settings WHERE key='completed_courses'").first();
  const result = await DB.prepare('SELECT id, session_date AS date, client, topic, duration FROM coaching_sessions ORDER BY id DESC').all();
  return {completed: JSON.parse(saved.value), hours: result.results};
}
